/// `Option<String>`: boolean `false` → `None`, boolean `true` →
/// `Some("")`, string → `Some(string)`, and `null` → `None`.
fn deserialize_deprecated<'de, D>(deserializer: D) -> Result<Option<String>, D::Error>
where
    D: Deserializer<'de>,
{
    struct DeprecatedVisitor;

    impl<'de> de::Visitor<'de> for DeprecatedVisitor {
        type Value = Option<String>;

        fn expecting(&self, formatter: &mut fmt::Formatter) -> fmt::Result {
            formatter.write_str("a boolean, a string, or null")
        }

        fn visit_bool<E>(self, deprecated: bool) -> Result<Self::Value, E> {
            Ok(deprecated.then(String::new))
        }

        fn visit_str<E>(self, message: &str) -> Result<Self::Value, E> {
            Ok(Some(message.to_owned()))
        }

        fn visit_string<E>(self, message: String) -> Result<Self::Value, E> {
            Ok(Some(message))
        }

        fn visit_none<E>(self) -> Result<Self::Value, E> {
            Ok(None)
        }

        fn visit_unit<E>(self) -> Result<Self::Value, E> {
            Ok(None)
        }

        fn visit_some<D>(self, deserializer: D) -> Result<Self::Value, D::Error>
        where
            D: Deserializer<'de>,
        {
            deserializer.deserialize_any(self)
        }
    }

